#ifndef IMAGE_PROCESSING_SIMULATION_H
#define IMAGE_PROCESSING_SIMULATION_H

#include "../software/image_processing.hpp"
#include "../obj_dir/Vimage_processing.h"

struct Operation{
   bool is_command;
   Commands command;
   uint8_t data;

   Operation(bool is_command, Commands com, uint8_t data){
      this->is_command = is_command;
      this->command = com;
      this->data = data;
   }
};

typedef std::queue<Operation> FIFO_OP;

class Image_processing_simulation : public Image_processing{
public:
   Image_processing_simulation();
   ~Image_processing_simulation();

   virtual void send_params(uint16_t img_width, uint16_t img_height);
   virtual void read_status(uint8_t *output); //TODO vector?
   virtual void send_image(uint8_t *img);

   virtual void send_add(int16_t value, bool clamp);
   virtual void send_threshold(uint8_t threshold_value, uint8_t replacement, bool upper_selection);
   virtual void send_image_invert();
   virtual void send_mult(float value, bool clamp);

   virtual void wait_end_busy();

   virtual void read_image(uint8_t *img);

   virtual void switch_buffers();

   virtual void send_binary_add(bool clamp);
   virtual void send_binary_sub(bool clamp, bool absolute_diff);
   virtual void send_binary_mult(bool clamp);
   virtual void send_convolution(uint8_t *kernel, bool clamp, bool input_source, bool add_to_output);
   virtual void send_clear(uint8_t value);

private:
   void main_loop_clk();

   Vimage_processing *simulator;
   FIFO_OP fifo_in;
   std::queue<uint16_t> fifo_out;

   uint16_t *memory;
};

#endif

//ice40 has 1024 kbit of spram ==> 128KB

// wire [31:0] ip_mem_addr;
// wire ip_mem_wr_en;
// wire ip_mem_rd_en;
// wire [15:0] ip_mem_data_write;
// wire [15:0] ip_mem_data_read;
// wire ip_mem_data_read_valid;

module ram_interface(input clk, input [31:0] addr, input wr_en, input rd_en, input [15:0] data_write, output reg [15:0] data_read, output reg data_read_valid);

   wire ram_wren [3:0];

   wire [15:0] ram_data_out [3:0];

   reg [1:0] output_mux [1:0];
   reg rd_en_buffer[2:0];


   SB_SPRAM256KA spram0
   (
      .ADDRESS(addr[14:1]), //14bits (16K*2B)
      .DATAIN(data_write),
      .MASKWREN(4'b1111),
      .WREN(ram_wren[0]),
      .CHIPSELECT(1'b1),
      .CLOCK(clk),
      .STANDBY(1'b0),
      .SLEEP(1'b0),
      .POWEROFF(1'b1),
      .DATAOUT(ram_data_out[0])
   );

   SB_SPRAM256KA spram1
   (
      .ADDRESS(addr[14:1]),
      .DATAIN(data_write),
      .MASKWREN(4'b1111),
      .WREN(ram_wren[1]),
      .CHIPSELECT(1'b1),
      .CLOCK(clk),
      .STANDBY(1'b0),
      .SLEEP(1'b0),
      .POWEROFF(1'b1),
      .DATAOUT(ram_data_out[1])
   );

   SB_SPRAM256KA spram2
   (
      .ADDRESS(addr[14:1]),
      .DATAIN(data_write),
      .MASKWREN(4'b1111),
      .WREN(ram_wren[2]),
      .CHIPSELECT(1'b1),
      .CLOCK(clk),
      .STANDBY(1'b0),
      .SLEEP(1'b0),
      .POWEROFF(1'b1),
      .DATAOUT(ram_data_out[2])
   );

   SB_SPRAM256KA spram3
   (
      .ADDRESS(addr[14:1]),
      .DATAIN(data_write),
      .MASKWREN(4'b1111),
      .WREN(ram_wren[3]),
      .CHIPSELECT(1'b1),
      .CLOCK(clk),
      .STANDBY(1'b0),
      .SLEEP(1'b0),
      .POWEROFF(1'b1),
      .DATAOUT(ram_data_out[3])
   );

   assign ram_wren[addr[16:15]] = wr_en;

   always @(posedge clk)
   begin
      output_mux[0] <= addr[16:15];
      output_mux[1] <= output_mux[0];
      rd_en_buffer[0] <= rd_en;
      rd_en_buffer[1] <= rd_en_buffer[0];
      rd_en_buffer[2] <= rd_en_buffer[1];
      data_read_valid <= (rd_en_buffer[2] == 0 && rd_en_buffer[1] == 1);
      data_read <= ram_data_out[output_mux[1]];
   end

endmodule

