241	      }
242	      else{
243	         simulator->comm_data_in_valid = 1;
244	         simulator->comm_data_in = op.data;
245	      }
246	   }
247	
248	   if(simulator->comm_data_out_valid == 1){
249	      fifo_out.push(simulator->comm_data_out);
250	      counter_free = 3;
251	      simulator->comm_data_out_free = (counter_free == 0);
252	   }
